contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // This contract rejects any incoming ether transfer.
    fallback() external payable {
        revert();
    }

    function test(address recipient) external {
        require(recipient == address(this));
        bool ok; c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
        // The bonus withdrawal sends ether to this rejecting contract, so the
        // outer call must revert (ok == false) on P. In M the failed transfer
        // is silently ignored, so ok == true there.
        assert(ok == false);
    }
}

