pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _test(address recipient) internal {
        recipient = address(this);
        bool ok;
        try c.getFirstWithdrawalBonus(recipient) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }

    function testFuzz_test(address recipient) public {
        _test(recipient);
    }

    fallback() external payable {
        revert();
    }
}
